package com.mendes.scheduling_platform.blockedperiod; import com.mendes.scheduling_platform.security.TenantContext; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/venues/{venueId}/blocked-periods") public class BlockedPeriodController {private final BlockedPeriodService s;public BlockedPeriodController(BlockedPeriodService s){this.s=s;}@GetMapping List<BlockedPeriod> list(@PathVariable Long venueId){return s.list(TenantContext.getRequired(),venueId);}@PostMapping BlockedPeriod add(@PathVariable Long venueId,@RequestBody BlockedPeriod b){return s.save(TenantContext.getRequired(),venueId,b);}@DeleteMapping("/{id}") void del(@PathVariable Long venueId,@PathVariable Long id){s.delete(TenantContext.getRequired(),id);}}
